const item = $input.first().json;
const UMBRAL_CONFIANZA = 0.75;

// El modelo devuelve texto libre (sin Structured Output Parser, por el
// bug de envoltorio detectado). Se parsea a mano, tolerando bloques
// markdown y un posible envoltorio extra en 'output'.
let raw = item.output;
if (raw && typeof raw === 'object') {
  raw = raw.output && typeof raw.output === 'object' ? raw.output : raw;
} else {
  raw = (raw || '').toString().replace(/```json|```/g, '').trim();
  try {
    const parsed = JSON.parse(raw);
    raw = (parsed.output && typeof parsed.output === 'object') ? parsed.output : parsed;
  } catch (e) {
    raw = null;
  }
}

let data = raw;
if (data && typeof data.tipo === 'string') {
  data = { ...data, tipo: data.tipo.toLowerCase() };
}

if (!data || !['armado', 'personalizado'].includes(data.tipo)) {
  data = { tipo: 'personalizado', paises_mencionados: [], fechas_mencionadas: null, cantidad_personas: null, resumen: 'Clasificacion invalida, escalado para revision.', confianza: 0, motivo: 'Salida invalida del modelo.' };
}

const n = Number(data.confianza);
const confianza = Number.isFinite(n) ? n : 0;

if (data.tipo === 'armado' && confianza < UMBRAL_CONFIANZA) {
  data.tipo = 'personalizado';
}

const paises = Array.isArray(data.paises_mencionados)
  ? data.paises_mencionados.filter(p => typeof p === 'string' && p.trim())
  : [];

return [{
  json: {
    status: 'success',
    data: {
      tipo: data.tipo,
      paises_mencionados: paises,
      requiere_pregunta_paises: data.tipo === 'armado' && paises.length === 0,
      fechas_mencionadas: data.fechas_mencionadas || null,
      cantidad_personas: (data.cantidad_personas !== undefined && data.cantidad_personas !== null) ? Number(data.cantidad_personas) : null,
      resumen: data.resumen || '',
      confianza,
      umbral: UMBRAL_CONFIANZA,
      motivo: data.motivo || ''
    },
    meta: { worker: 'worker_compra', model: 'gemini-agent' }
  }
}];

const err = $input.first().json;
return [{
  json: {
    status: 'error',
    data: {
      tipo: 'personalizado',
      paises_mencionados: [],
      requiere_pregunta_paises: false,
      fechas_mencionadas: null,
      cantidad_personas: null,
      resumen: '',
      confianza: 0,
      umbral: 0.75,
      motivo: 'No se pudo evaluar automaticamente: el Worker fallo.',
      reason: 'worker_call_failed',
      detail: (err.error && err.error.message) || err.message || 'Error desconocido al invocar el modelo'
    },
    meta: { worker: 'worker_compra' }
  }
}];
